+        radial-gradient(circle at bottom right, rgba(99, 102, 241, 0.18), transparent 28rem),
+        var(--bg);
+      color: var(--text);
+      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
+    }
+
+    main {
+      width: min(100%, 520px);
+    }
+
+    .support-card {
+      padding: 36px;
+      border: 1px solid var(--panel-border);
+      border-radius: 28px;
+      background: linear-gradient(145deg, rgba(30, 41, 59, 0.94), var(--panel));
+      box-shadow: 0 24px 80px var(--shadow);
+      backdrop-filter: blur(16px);
+    }
+
+    .eyebrow {
+      margin: 0 0 10px;
+      color: var(--accent);
+      font-size: 0.78rem;
+      font-weight: 700;
+      letter-spacing: 0.14em;
+      text-transform: uppercase;
+    }
+
+    h1 {
+      margin: 0;
+      font-size: clamp(2rem, 8vw, 3rem);
+      line-height: 1;
+      letter-spacing: -0.045em;
+    }
+
+    .intro {
+      margin: 16px 0 30px;
+      color: var(--muted);
+      font-size: 1rem;
+      line-height: 1.6;
+    }
+
+    form {
+      display: grid;
+      gap: 18px;
+    }
+
+    .form-field {
+      display: grid;
+      gap: 8px;
+    }
+
+    label {
+      color: #dbeafe;
+      font-size: 0.92rem;
+      font-weight: 700;
+    }
+
+    .required {
+      color: var(--accent);
+    }
+
+    input {
+      width: 100%;
+      border: 1px solid var(--field-border);
+      border-radius: 16px;
+      background: var(--field);
+      color: var(--text);
+      font: inherit;
+      padding: 15px 16px;
+      outline: none;
+      transition: border-color 160ms ease, box-shadow 160ms ease, background 160ms ease;
+    }
+
+    input::placeholder {
+      color: #64748b;
+    }
+
+    input:focus {
+      border-color: var(--accent);
+      background: rgba(15, 23, 42, 0.98);
+      box-shadow: 0 0 0 4px rgba(56, 189, 248, 0.14);
+    }
+
+    input:user-invalid {
+      border-color: var(--danger);
+      box-shadow: 0 0 0 4px rgba(251, 113, 133, 0.12);
+    }
+
+    .helper-text {
+      margin: 0;
+      color: var(--muted);
+      font-size: 0.86rem;
+      line-height: 1.45;
+    }
+
+    button {
+      margin-top: 8px;
+      border: 0;
+      border-radius: 16px;
+      background: linear-gradient(135deg, var(--accent), var(--accent-strong));
+      color: #07111f;
+      cursor: pointer;
+      font: inherit;
+      font-weight: 800;
+      padding: 15px 18px;
+      transition: transform 160ms ease, filter 160ms ease, box-shadow 160ms ease;
+      box-shadow: 0 14px 32px rgba(14, 165, 233, 0.28);
+    }
+
+    button:hover {
+      filter: brightness(1.05);
+      transform: translateY(-1px);
+    }
+
+    button:focus-visible {
+      outline: 3px solid rgba(186, 230, 253, 0.85);
+      outline-offset: 3px;
+    }
+
+    .form-status {
+      min-height: 1.4em;
+      margin: 2px 0 0;
+      color: #86efac;
+      font-size: 0.94rem;
+      font-weight: 700;
+    }
+
+    @media (max-width: 520px) {
+      .support-card {
+        padding: 28px 22px;
+        border-radius: 22px;
+      }
+    }
+  </style>
+</head>
+<body>
+  <main>
+    <section class="support-card" aria-labelledby="support-title">
+      <p class="eyebrow">Support request</p>
+      <h1 id="support-title">How can we help?</h1>
+      <p class="intro">Send our support team your contact details and we will get back to you as soon as possible.</p>
+
+      <form id="support-form" novalidate>
+        <div class="form-field">
+          <label for="full-name">Full name <span class="required" aria-hidden="true">*</span></label>
+          <input
+            type="text"
+            id="full-name"
+            name="fullName"
+            autocomplete="name"
+            placeholder="Alex Morgan"
+            required
+          >
+        </div>
+
+        <div class="form-field">
+          <label for="email">Email address <span class="required" aria-hidden="true">*</span></label>
+          <input
+            type="email"
+            id="email"
+            name="email"
+            autocomplete="email"
+            placeholder="alex@example.com"
+            required
+          >
+        </div>
+
+        <div class="form-field">
+          <label for="phone">Phone number</label>
+          <input
+            type="tel"
+            id="phone"
+            name="phone"
+            autocomplete="tel"
+            inputmode="tel"
+            placeholder="+1 555 123 4567"
+            aria-describedby="phone-helper"
+          >
+          <p class="helper-text" id="phone-helper">Expected format: country code followed by the area code and number, such as +1 555 123 4567.</p>
+        </div>
+
+        <button type="submit">Contact support</button>
+        <p class="form-status" id="form-status" role="status" aria-live="polite"></p>
+      </form>
+    </section>
+  </main>
+
+  <script>
+    const form = document.querySelector("#support-form");
+    const statusMessage = document.querySelector("#form-status");
+
+    form.addEventListener("submit", (event) => {
+      event.preventDefault();
+      statusMessage.textContent = "";
+
+      if (!form.checkValidity()) {
+        form.reportValidity();
+        return;
+      }
+
+      statusMessage.textContent = "Thanks! Your support request is ready to send.";
+      form.reset();
+    });
+  </script>
+</body>
+</html>
*** End Patch
